const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const languageControl=()=>typeof languageSwitcher==='function'?languageSwitcher():'';
const paths={discover:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',orders:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 8h6 M9 12h6',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',restaurant:'M4 3v7c0 3 6 3 6 0V3 M7 3v18 M18 3c-4 4-4 8 0 8v10 M18 3v8',admin:'M12 3l8 4v6c0 5-8 9-8 9s-8-4-8-9V7z M9 12l2 2 4-4',pin:'M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0z M9 10a3 3 0 1 0 6 0 3 3 0 1 0-6 0',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 1 1 14 0',delivery:'M3 6h12v12H3z M15 10h4l3 5v3h-7 M5 18a2 2 0 1 0 4 0 M16 18a2 2 0 1 0 4 0',bag:'M4 7h16l1 14H3z M8 8V6a4 4 0 0 1 8 0v2',arrow:'M4 12h16 M14 6l6 6-6 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.discover}"/></svg>`;
const photo=(id,w=900)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const photos=['photo-1414235077428-338989a2e8c0','photo-1555396273-367ea4eb4db5','photo-1517248135467-4c7edcad34c4','photo-1552566626-52f8b828add9','photo-1559339352-11d035aa65de','photo-1514933651103-005eec06c04b'];
let db={restaurants:[],menus:{},orders:[],bookings:[],favorites:JSON.parse(localStorage.getItem('dayin-favorites')||'[]')};let page='discover',mode='delivery',category='Все',halalOnly=false,query='',current='r1',cart={},cartRestaurant=null,tab='orders';
const save=()=>localStorage.setItem('dayin-favorites',JSON.stringify(db.favorites)),money=n=>Number(n).toLocaleString('ru-RU')+' ₸',menu=r=>db.menus[r]||[],restaurant=()=>db.restaurants.find(r=>r.id===current)||db.restaurants[0];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}

function card(r){return `<article class="card"><div class="cardphoto"><img loading="lazy" src="${photo(r.img)}" alt="Интерьер ${esc(r.name)}"><span class="badge">${esc(r.tag||'Новое место')}</span><button class="fav ${db.favorites.includes(r.id)?'on':''}" aria-label="${db.favorites.includes(r.id)?'Удалить из':'Добавить в'} избранное" onclick="favorite('${r.id}')">${icon('heart')}</button></div><div class="cardbody"><div class="cardtitle"><h3><button onclick="openRestaurant('${r.id}')">${esc(r.name)}</button></h3><div class="rating"><span>★</span> ${esc(r.rating)}</div></div>${halalBadge(r)}<div class="meta">${esc(r.desc)} · ${money(r.avg)}</div><div class="cardbottom"><span class="open">● Открыто <span class="muted">· ${mode==='delivery'?r.time+' мин':mode==='pickup'?'Самовывоз':'Есть столики'}</span></span><button onclick="${mode==='booking'?`book('${r.id}')`:`openRestaurant('${r.id}')`}">${mode==='booking'?'Забронировать':'Смотреть меню'} ↗</button></div></div></article>`}
function catalog(){let list=db.restaurants.filter(r=>(page!=='favorites'||db.favorites.includes(r.id))&&matchesCuisine(r)&&(!halalOnly||halalState(r)==='verified')&&(`${r.name} ${cuisinesLabel(r)} ${r.desc}`.toLowerCase().includes(query.toLowerCase())));return `${page==='discover'?`<section class="hero"><img src="${photo(photos[0],1600)}" alt="Уютный ресторан с тёплым освещением"><div class="hero-copy"><div class="eyebrow">ВАШ ГОРОД НА ВКУС</div><h1>Хорошие места.<br>Вкусные моменты.</h1><p>Найдите место для встречи, забронируйте столик или закажите любимое домой.</p><button onclick="document.getElementById('places').scrollIntoView({behavior:'smooth'})">Найти своё место &nbsp; ↗</button></div><div class="hero-note">Маленькие открытия. Каждый день.</div></section><div class="modebar"><div class="segments">${[['delivery','Доставка','delivery'],['pickup','Самовывоз','bag'],['booking','Столик','calendar']].map(([m,l,i])=>`<button class="${mode===m?'selected':''}" onclick="mode='${m}';render()">${icon(i)}${l}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" aria-label="Поиск ресторана или кухни" value="${esc(query)}" placeholder="Ресторан, кухня или настроение" oninput="searchPlaces(this.value)"></label></div>`:''}<div class="sectionhead" id="places"><div><h2>${page==='favorites'?'Ваши любимые места':'Места, которые вам понравятся'}</h2><p>${page==='favorites'?'Сохраните заведения, чтобы вернуться к ним':(catalogTotal||list.length)+' '+((catalogTotal||list.length)===1?'заведение':'заведений')+' · Зарегистрированы на платформе'}</p></div><button class="quiet city-inline" onclick="chooseCity()">Атырау ⌄</button></div>${catalogFilters()}<div class="grid" id="cards">${list.length?list.map(card).join(''):catalogEmpty()}</div>${moreRestaurantsButton()}${page==='discover'?`<section class="editorial"><div><div class="eyebrow" style="margin-bottom:8px">ВСТРЕЧИ, КОТОРЫЕ ВАЖНЫ</div><h2>Для двоих. Для друзей. Для себя.</h2><p>Хороший вечер начинается с правильного столика.</p></div><button class="primary" onclick="mode='booking';render();document.getElementById('places').scrollIntoView()">Выбрать ресторан &nbsp; ↗</button></section>`:''}`}
function searchPlaces(v){query=v;const pos=$('#search').selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);scheduleCatalogRefresh()}function favorite(id){db.favorites=db.favorites.includes(id)?db.favorites.filter(x=>x!==id):[...db.favorites,id];save();render()}
function detail(){const r=restaurant(),otherCart=cartRestaurant&&cartRestaurant!==r.id&&Object.keys(cart).length;return `<button class="back" onclick="nav('discover')">← Все заведения</button><div class="subheading"><div><div class="eyebrow">${esc(cuisinesLabel(r))} КУХНЯ</div><div class="restaurant-name-row"><h1>${esc(r.name)}</h1>${halalBadge(r)}</div><p style="margin:0">★ ${esc(r.rating)} &nbsp; · &nbsp; ${esc(r.address)} &nbsp; · &nbsp; 10:00–23:00</p></div><button class="primary" onclick="book('${r.id}')">Забронировать столик</button></div><div class="restaurant-cover"><img src="${photo(r.img,1600)}" alt="${esc(r.name)}"></div><div class="detail-layout"><section>${otherCart?'<div class="notice">В корзине уже есть блюда из другого ресторана. Оформите заказ или очистите корзину, чтобы заказать здесь. <button class="quiet" onclick="nav(\'cart\')">Открыть корзину →</button></div>':''}<h2>Меню ресторана</h2><p>Приготовим к вашему приезду или привезём домой.</p>${deliveryNotice(r,true)}<div class="panel">${menuCategoryTabs(r.id)}<div id="menu-dishes" role="tabpanel" aria-label="Блюда категории" ontouchstart="startMenuSwipe(event)" ontouchend="endMenuSwipe(event)">${visibleDishes(r.id).map(d=>`<article class="dish"><img loading="lazy" src="${photo(d.img,250)}" alt="${esc(d.name)}"><div class="dish-info"><h3>${esc(d.name)}</h3><p>${esc(d.desc)}</p><strong>${money(d.price)}</strong></div><button class="add" ${otherCart?'disabled':''} aria-label="Добавить ${esc(d.name)} в корзину" onclick="add('${d.id}')">+</button></article>`).join('')}</div></div></section><aside><div class="panel"><h3>Ваш заказ</h3><div class="segments" style="font-size:11px;margin-bottom:15px"><button class="${mode!=='pickup'?'selected':''}" onclick="mode='delivery';persistCart();render()" ${otherCart?'disabled':''} style="padding:9px 12px">Доставка</button><button class="${mode==='pickup'?'selected':''}" onclick="mode='pickup';persistCart();render()" ${otherCart?'disabled':''} style="padding:9px 12px">Самовывоз</button></div>${cartRestaurant===r.id&&Object.keys(cart).length?Object.entries(cart).map(([id,q])=>{let d=menu(r.id).find(x=>x.id===id);return d?`<div class="cartline"><span>${esc(d.name)}<br><strong>${money(d.price*q)}</strong></span><div class="qty"><button aria-label="Уменьшить количество" onclick="adjust('${id}',-1)">−</button>${q}<button aria-label="Увеличить количество" onclick="adjust('${id}',1)">+</button></div></div>`:''}).join(''):'<p style="font-size:12px;text-align:center;padding:22px 0">Выберите что-нибудь вкусное<br>из меню ресторана</p>'}${deliveryNotice(r)}<div class="total"><span>Сумма блюд</span><span>${money(cartRestaurant===r.id?total():0)}</span></div><button class="primary full" onclick="checkout()">Перейти к оформлению</button><p style="font-size:10px;margin-bottom:0">Оплата при получении</p></div></aside></div>`}
const DISH_CATEGORIES=['Салаты','Закуски','Супы','Горячие блюда','Паста','Фастфуд','Пицца','Суши и роллы','Десерты','Напитки','Другое'];
let selectedDishCategory='Все блюда',menuSwipeStart=null;
function dishCategory(d){return DISH_CATEGORIES.includes(d.category)?d.category:({'Салат с burrata':'Салаты','Паста с грибами':'Паста','Лосось на гриле':'Горячие блюда','Тирамису':'Десерты'}[d.name]||'Другое')}
function dishCategorySelect(value='Другое'){return `<select name="category" aria-label="Категория блюда">${DISH_CATEGORIES.map(c=>`<option value="${c}" ${c===value?'selected':''}>${c}</option>`).join('')}</select>`}
function menuCategories(id){const present=new Set(menu(id).map(dishCategory));return ['Все блюда',...DISH_CATEGORIES.filter(c=>present.has(c))]}
function visibleDishes(id){if(!menuCategories(id).includes(selectedDishCategory))selectedDishCategory='Все блюда';return menu(id).filter(d=>selectedDishCategory==='Все блюда'||dishCategory(d)===selectedDishCategory)}
function menuCategoryTabs(id){if(!menuCategories(id).includes(selectedDishCategory))selectedDishCategory='Все блюда';return `<div class="menu-categories" role="tablist" aria-label="Категории блюд">${menuCategories(id).map((c,i)=>`<button type="button" role="tab" aria-selected="${c===selectedDishCategory}" aria-controls="menu-dishes" tabindex="${c===selectedDishCategory?'0':'-1'}" onclick="selectDishCategory(${i})" onkeydown="menuCategoryKey(event,${i})">${c}</button>`).join('')}</div>`}
function selectDishCategory(index,focus=false){const categories=menuCategories(current);if(index<0||index>=categories.length)return;const offset=document.querySelector('.menu-categories')?.scrollLeft||0;selectedDishCategory=categories[index];render();const rail=document.querySelector('.menu-categories');if(rail){rail.scrollLeft=offset;const button=rail.querySelector('[aria-selected="true"]');button?.scrollIntoView?.({behavior:'smooth',block:'nearest',inline:'nearest'});if(focus)button?.focus()}}
function menuCategoryKey(event,index){if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();const n=menuCategories(current).length;selectDishCategory((index+(event.key==='ArrowRight'?1:n-1))%n,true)}}
function startMenuSwipe(event){if(event.touches.length!==1){menuSwipeStart=null;return}menuSwipeStart={x:event.touches[0].clientX,y:event.touches[0].clientY}}
function endMenuSwipe(event){if(!menuSwipeStart||!event.changedTouches.length)return;const dx=event.changedTouches[0].clientX-menuSwipeStart.x,dy=event.changedTouches[0].clientY-menuSwipeStart.y;menuSwipeStart=null;if(Math.abs(dx)<60||Math.abs(dx)<Math.abs(dy)*1.5)return;const list=menuCategories(current),index=list.indexOf(selectedDishCategory);selectDishCategory(index+(dx<0?1:-1))}
function total(){let sum=Object.entries(cart).reduce((s,[id,q])=>s+(menu(cartRestaurant).find(d=>d.id===id)?.price||0)*q,0);return sum}
function deliveryNotice(r,always=false){if(!r||(!always&&mode==='pickup'))return '';const threshold=r.freeDeliveryAbove,enabled=Number.isInteger(threshold)&&threshold>=0,free=enabled&&cartRestaurant===r.id&&cartCount()>0&&total()>threshold;return `<div class="notice delivery-notice">${enabled?`<strong>${free&&!always?'Для этого заказа доставка бесплатная':'Бесплатная доставка при заказе свыше '+money(threshold)}</strong>`:''}${!always&&!free?'<p>Условия доставки уточнит ресторан при подтверждении.</p>':''}</div>`}
function add(id){if(orderSubmitting)return;if(cartRestaurant&&cartRestaurant!==current&&Object.keys(cart).length){toast('В корзине уже есть блюда из другого ресторана. Оформите заказ или очистите корзину.');return}if(!menu(current).some(d=>d.id===id))return;cartRestaurant=current;cart[id]=Math.min((cart[id]||0)+1,99);persistCart();render()}function adjust(id,n){if(orderSubmitting||!cart[id])return;cart[id]+=n;if(cart[id]<=0)delete cart[id];if(!Object.keys(cart).length)cartRestaurant=null;persistCart();render()}
function modal(title,body){$('#modal').innerHTML=`<div class="modalhead"><h2>${title}</h2><button aria-label="Закрыть" onclick="$('#modal').close()">×</button></div>${body}`;$('#modal').showModal()}

function book(id){const r=db.restaurants.find(x=>x.id===id);modal('Столик в '+esc(r.name),`<p>Выберите время, а мы сохраним вашу заявку.</p><form class="form" onsubmit="submitBooking(event,'${id}')"><div class="formrow"><label>Дата<input name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required></label><label>Время<select name="time">${['12:00','13:00','14:00','17:00','18:00','19:00','20:00','21:00'].map(t=>`<option>${t}</option>`).join('')}</select></label></div><label>Количество гостей · максимум ${r.maxGuests??8}<select name="guests">${Array.from({length:r.maxGuests??8},(_,i)=>i+1).map(n=>`<option ${n===2?'selected':''}>${n}</option>`).join('')}</select></label><label>Ваше имя<input name="name" value="${isCustomer()?esc(authUser.name):''}" required maxlength="80" autocomplete="name"></label><label>Телефон<input name="phone" type="tel" required pattern="[+0-9 ()-]{10,20}" placeholder="+7 700 123 45 67" autocomplete="tel"></label><label>Пожелания<textarea name="note" placeholder="Например, столик у окна" maxlength="300"></textarea></label><div class="notice">Заявка появится в личном кабинете ресторана. Дождитесь подтверждения.</div><button class="primary">Отправить заявку</button></form>`)}

function checkout(){if(!Object.keys(cart).length||cartRestaurant!==current){toast('Добавьте блюда в корзину');return}modal('Оформление заказа',`<p>${esc(restaurant().name)} · ${mode==='pickup'?'Самовывоз':'Доставка'} · ${money(total())}</p>${deliveryNotice(restaurant())}<form class="form" onsubmit="submitOrder(event)"><label>Ваше имя<input name="name" required maxlength="80" autocomplete="name"></label><label>Телефон<input name="phone" type="tel" required pattern="[+0-9 ()-]{10,20}" placeholder="+7 700 123 45 67" autocomplete="tel"></label>${mode!=='pickup'?'<label>Адрес доставки<input name="address" required maxlength="200" placeholder="Улица, дом, квартира" autocomplete="street-address"></label>':`<div class="notice">Заберите заказ: ${esc(restaurant().address)}. Время готовности уточняется после подтверждения.</div>`}<label>Комментарий<textarea name="note" maxlength="300" placeholder="Приборы, домофон, пожелания"></textarea></label><div class="notice">Оплата при получении. Заказ поступит в личный кабинет заведения.</div><button class="primary">Создать заказ · ${money(total())}</button></form>`)}

function history(){const b=page==='bookings',list=b?db.bookings:db.orders;return `<div class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</div><h1>${b?'Ваши бронирования':'Ваши заказы'}</h1><p>${b?'Планы на хороший вечер':'Всё, что вы выбрали, в одном месте'}</p>${list.length?list.map(o=>`<div class="panel orderitem"><div class="subheading"><h3>${esc(db.restaurants.find(r=>r.id===o.restaurant)?.name)}</h3><span class="status">${esc(o.status)}</span></div><p>${b?`${esc(o.date)} · ${esc(o.time)} · Гостей: ${esc(o.guests)}`:`${esc(o.date)} · ${esc(o.mode)} · ${money(o.total)}`}</p>${!b?`<p>${o.items.map(d=>`${esc(d.name)} × ${d.qty}`).join(' · ')}</p>`:''}${!['Отменён','Завершён','Отменено'].includes(o.status)?`<button class="secondary" onclick="cancel('${b?'bookings':'orders'}','${o.id}')">${b?'Отменить бронь':'Отменить заказ'}</button>`:''}</div>`).join(''):`<div class="empty"><h2>${b?'Здесь будут ваши встречи':'Пока нет заказов'}</h2><p>${b?'Выберите ресторан и отправьте заявку на столик.':'Откройте меню и выберите любимые блюда.'}</p><button class="primary" onclick="nav('discover')">Открыть заведения</button></div>`}`}

function business(){const r=restaurant(),orders=db.orders.filter(o=>o.restaurant===r.id),bookings=db.bookings.filter(o=>o.restaurant===r.id);return `<div class="subheading"><div><div class="eyebrow">КАБИНЕТ РЕСТОРАНА</div><h1>${esc(r.name)}</h1><p>Заказы, гости и меню — под вашим контролем.</p></div>${authUser?.role==='admin'?`<select class="secondary" aria-label="Выбрать ресторан" onchange="current=this.value;render()">${db.restaurants.map(x=>`<option value="${x.id}" ${current===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:`<button class="secondary" onclick="newRestaurant(current)">Настройки заведения</button>`}</div><div class="stats"><div class="stat"><small>Заказы</small><strong>${orders.length}</strong><small>Всего заказов</small></div><div class="stat"><small>Сумма заказов</small><strong>${money(orders.filter(x=>x.status!=='Отменён').reduce((s,o)=>s+o.total,0))}</strong><small>Без отменённых</small></div><div class="stat"><small>Бронирования</small><strong>${bookings.length}</strong><small>Заявки гостей</small></div></div><div class="tabs">${[['orders','Заказы'],['bookings','Бронирования'],['menu','Редактор меню'],['qr','QR меню'],['integrations','Интеграции']].map(([t,l])=>`<button class="${tab===t?'selected':''}" onclick="tab='${t}';render()">${l}</button>`).join('')}</div>${tab==='qr'?qrPanel():tab==='integrations'?integrations():tab==='menu'?editMenu():`<div class="panel"><h3>${tab==='orders'?'Входящие заказы':'Заявки на столики'}</h3>${workTable(tab==='orders'?orders:bookings,tab)}</div>`}`}
function workTable(list,kind){return list.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Гость</th><th>${kind==='orders'?'Заказ':'Визит'}</th><th>Детали</th><th>Статус</th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>${esc(o.name)}</strong><br>${esc(o.phone)}</td><td>${kind==='orders'?money(o.total)+'<br>'+esc(o.mode):esc(o.date)+'<br>'+esc(o.time)}</td><td>${kind==='orders'?o.items.map(x=>esc(x.name)+' × '+x.qty).join('<br>')+'<br>'+esc(o.address||'Самовывоз'):esc(o.guests)+' гостей'}<br><span class="muted">${esc(o.note)}</span></td><td><select class="secondary" aria-label="Статус заявки ${esc(o.name)}" onchange="updateStatus('${kind}','${o.id}',this.value)">${(kind==='orders'?['Новый','Принят','Готовится','Готов к выдаче','В пути','Завершён','Отменён']:['Ожидает подтверждения','Подтверждено','Гости пришли','Отменено']).filter(s=>!(o.mode==='Самовывоз'&&s==='В пути')).map(s=>`<option value="${esc(s)}" ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><p>Новых заявок пока нет. Здесь появятся заказы и бронирования ваших гостей.</p></div>'}

function integrations(){return `<p>Будущие подключения к кассе, учётной системе и доставке. Для подключения понадобятся договоры, API-доступ и серверная интеграция.</p><div class="grid">${[['iiko','Меню, заказы и стоп-лист'],['r_keeper','Касса и учёт продаж'],['Poster','Синхронизация каталога'],['Доставка','Передача заказов курьерам'],['Платежи','Приём онлайн-оплаты'],['Webhooks','События заказов и бронирований']].map(([n,d])=>`<div class="panel integration"><b>${esc(n.slice(0,2))}</b><div><strong>${n}</strong><p>${d}</p><span class="status">Не подключено</span></div></div>`).join('')}</div>`}
function editMenu(){return `<div class="panel"><div class="subheading"><h3>Меню · ${menu(current).length} блюда</h3><button class="primary" onclick="newDish()">+ Добавить блюдо</button></div><p>Изменения сразу появятся в меню заведения.</p>${menu(current).map(d=>`<form class="menuedit" onsubmit="saveDish(event,'${d.id}')"><input aria-label="Название блюда" name="name" value="${esc(d.name)}" required maxlength="100">${dishCategorySelect(d.category)}<input aria-label="Цена в тенге" name="price" value="${d.price}" type="number" min="1" max="1000000" required><button class="secondary" style="padding:12px 4px">OK</button></form>`).join('')}</div>`}

function newDish(){modal('Новое блюдо',`<form class="form" onsubmit="submitDish(event)"><label>Название<input name="name" required maxlength="100"></label><label>Описание<textarea name="desc" required maxlength="300"></textarea></label><label>Категория блюда${dishCategorySelect()}</label><label>Цена, ₸<input name="price" type="number" min="1" max="1000000" required></label><button class="primary">Добавить в меню</button></form>`)}


function newRestaurant(id){let r=db.restaurants.find(x=>x.id===id)||{};modal(id?'Редактировать заведение':'Новое заведение',`<form class="form" onsubmit="submitRestaurant(event,'${id||''}')"><label>Название<input name="name" value="${esc(r.name||'')}" required maxlength="80"></label>${cuisineSettings(r)}<label>Краткое описание<input name="desc" value="${esc(r.desc||'')}" required maxlength="120"></label><label>Адрес в Атырау<input name="address" value="${esc(r.address||'')}" required maxlength="150"></label><label>Средний чек, ₸<input name="avg" type="number" min="1" max="1000000" value="${r.avg||5000}" required></label><label>Максимум гостей в одной брони<input name="maxGuests" type="number" min="1" max="100" step="1" value="${r.maxGuests??8}" required><small class="muted">Гости смогут выбрать от 1 до указанного количества. От 1 до 100 гостей.</small></label><label>Бесплатная доставка при заказе свыше, ₸<input name="freeDeliveryAbove" type="number" min="0" max="1000000" step="1" value="${r.freeDeliveryAbove??''}" placeholder="Например, 10000"><small class="muted">Оставьте пустым, если бесплатная доставка не предусмотрена.</small></label>${halalSettings(r)}<button class="primary">${id?'Сохранить':'Создать заведение'}</button></form>`)}

$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function openRestaurant(id){current=id;page="detail";render();window.scrollTo(0,0)}
